// Generated by scripts/generate_simd_api_parity.py.
// Tests boundary argument forwarding and float bits, against the existing tier.
#![forbid(unsafe_code)]
#![cfg(any(
    target_arch = "x86_64",
    target_arch = "aarch64",
    target_arch = "wasm32"
))]
#![allow(clippy::too_many_arguments)]
extern crate std;
use crate::{self as legacy, target_features as feature};
use alloc::vec::Vec;

fn data<const N: usize>(seed: usize) -> [f32; N] {
    core::array::from_fn(|i| ((i * 17 + seed * 13) % 97) as f32 * 0.03125 - 1.0)
}
fn bits(v: &[f32]) -> Vec<u32> {
    v.iter().map(|v| v.to_bits()).collect()
}
fn entropy_bits(v: legacy::EntropyCoeffResult) -> [u32; 4] {
    [
        v.entropy_sum.to_bits(),
        v.info_loss2_sum.to_bits(),
        v.info_loss_sum.to_bits(),
        v.nzeros_sum.to_bits(),
    ]
}

#[cfg(all(target_arch = "x86_64", feature = "avx512"))]
#[test]
fn entropy_coeffs_v4_matches_legacy() {
    use archmage::SimdToken;
    let _guard = archmage::testing::lock_token_testing();
    #[archmage::arcane]
    #[allow(deprecated)] // This test deliberately exercises the compatibility API.
    fn run(token: archmage::X64V4Token) {
        for (seed, width) in [(0, 16), (1, 17), (2, 32)] {
            let _ = (seed, width);
            let block_c = data::<4096>(seed);
            let block_y = data::<4096>(seed);
            let weights = [1.25_f32; 4096];
            let inv_weights = [1.25_f32; 4096];
            let mut error_coeffs_new = data::<4096>(seed);
            let mut error_coeffs_old = error_coeffs_new;
            let actual = feature::entropy_coeffs_v4(
                &block_c,
                &block_y,
                &weights,
                &inv_weights,
                width,
                0.75,
                0.75,
                0.75,
                0.75,
                seed % 2 == 0,
                &mut error_coeffs_new,
            );
            let expected = crate::entropy::entropy_coeffs_impl_v4(
                token,
                &block_c,
                &block_y,
                &weights,
                &inv_weights,
                width,
                0.75,
                0.75,
                0.75,
                0.75,
                seed % 2 == 0,
                &mut error_coeffs_old,
            );
            assert_eq!(entropy_bits(actual), entropy_bits(expected));
            assert_eq!(bits(&error_coeffs_new), bits(&error_coeffs_old));
        }
    }
    if let Some(token) = archmage::X64V4Token::summon() {
        run(token);
    } else {
        assert_ne!(
            std::env::var("JXL_REQUIRE_TOKEN").as_deref(),
            Ok("X64V4Token"),
            "required SIMD tier unavailable"
        );
    }
}

